queries=[head+':'+name for name in paths]
raw=subprocess.check_output(['git','cat-file','--batch'],input=('\n'.join(queries)+'\n').encode())
files={};offset=0
for name in paths:
 end=raw.index(b'\n',offset);identity,kind,size=raw[offset:end].split();assert kind==b'blob'
